Certainly! Below is an example of a Python script using Object-Oriented Programming (OOP) to implement a Contextual Multi-Armed Bandit problem with three models.

```python
import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def fit(self, X, y):
        # Simple linear regression using least squares
        self.weights = np.linalg.inv(X.T @ X) @ X.T @ y

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def predict(self, X):
        return np.random.rand(len(X))

class EpsilonGreedyBandit:
    def __init__(self, epsilon=0.1, models=None):
        if models is None:
            models = [LinearModel(), RandomModel()]
        self.epsilon = epsilon
        self.models = models
        self.best_model_index = None
        self.best_model_score = -np.inf

    def select_arm(self, context):
        if np.random.rand() < self.epsilon:
            arm = np.random.choice(len(self.models))
        else:
            predictions = [model.predict([context])[0] for model in self.models]
            arm = np.argmax(predictions)

        return arm

    def update(self, context, action, reward):
        prediction = self.models[action].predict([context])[0]
        self.models[action].fit([context], [reward])

        if prediction > self.best_model_score:
            self.best_model_index = action
            self.best_model_score = prediction

# Example usage
if __name__ == "__main__":
    # Generate some synthetic data
    np.random.seed(42)
    n_samples = 1000
    n_features = 5
    contexts = np.random.rand(n_samples, n_features)
    rewards = np.random.randint(0, 10, size=n_samples)

    # Initialize the bandit
    bandit = EpsilonGreedyBandit(epsilon=0.1)

    # Run the bandit algorithm
    for t in range(n_samples):
        context = contexts[t]
        action = bandit.select_arm(context)
        reward = rewards[t]
        bandit.update(context, action, reward)

    print(f"Best model index: {bandit.best_model_index}")
```

### Explanation:

1. **Model Class**: This is an abstract base class that defines the interface for different models. It has methods `fit` and `predict` which need to be implemented by subclasses.

2. **LinearModel Class**: A simple linear regression model that uses least squares to estimate weights.

3. **RandomModel Class**: A random model that generates random predictions.

4. **EpsilonGreedyBandit Class**: Implements the epsilon-greedy strategy for selecting actions based on the current estimates from the models. It also updates the models after receiving feedback.

5. **Example Usage**: Generates synthetic data, initializes the bandit, and runs the algorithm over multiple iterations.

This script provides a basic framework for implementing a contextual multi-armed bandit problem with multiple models. You can extend it further by adding more sophisticated models or strategies.

