public class WordMerger
{
    public static void MergeDocuments(string sourceDoc1Path, string sourceDoc2Path, string destinationDocPath)
    {
        // Load the first document
        using (WordprocessingDocument doc1 = WordprocessingDocument.Open(sourceDoc1Path, false))
        {
            MainDocumentPart mainPart1 = doc1.MainDocumentPart;

            // Copy header and footer
            foreach (HeaderPart headerPart in mainPart1.HeaderParts)
            {
                HeaderPart newHeaderPart = mainPart1.AddNewPart<HeaderPart>();
                newHeaderPart.FeedData(headerPart.GetStream());
            }

            foreach (FooterPart footerPart in mainPart1.FooterParts)
            {
                FooterPart newFooterPart = mainPart1.AddNewPart<FooterPart>();
                newFooterPart.FeedData(footerPart.GetStream());
            }

            // Copy styles
            StylesPart stylesPart1 = mainPart1.StyleDefinitionsPart;
            if (stylesPart1 != null)
            {
                StylesPart newStylesPart = mainPart1.AddNewPart<StylesPart>();
                newStylesPart.FeedData(stylesPart1.GetStream());
            }
        }

        // Load the second document
        using (WordprocessingDocument doc2 = WordprocessingDocument.Open(sourceDoc2Path, false))
        {
            MainDocumentPart mainPart2 = doc2.MainDocumentPart;

            // Get the body of the second document
            Body body2 = mainPart2.Document.Body;

            // Add the content of the second document's body to the first document's body
            using (WordprocessingDocument mergedDoc = WordprocessingDocument.Create(destinationDocPath, WordprocessingDocumentType.Document))
            {
                MainDocumentPart mainPartMerged = mergedDoc.MainDocumentPart;

                // Create a new body for the merged document
                Body bodyMerged = new Body();

                // Add the first two pages' content from the first document
                int pageCount = 0;
                foreach (Paragraph paragraph in mainPart1.Document.Body.Elements<Paragraph>())
                {
                    if (++pageCount > 2) break;
                    bodyMerged.Append(paragraph.CloneNode(true));
                }

                // Add the remaining content from the second document
                foreach (var element in body2.Elements())
                {
                    bodyMerged.Append(element.CloneNode(true));
                }

                // Add the glossary from the second document
                GlossaryDocumentPart glossaryPart = mainPart2.GlossaryDocumentPart;
                if (glossaryPart != null)
                {
                    GlossaryDocumentPart newGlossaryPart = mainPartMerged.AddNewPart<GlossaryDocumentPart>();
                    newGlossaryPart.FeedData(glossaryPart.GetStream());
                }

                // Set the merged body as the main document part's body
                mainPartMerged.Document = new Document(bodyMerged);

                // Save the merged document
                mergedDoc.Save();
            }
        }
    }
}
