Here is a JavaScript function to calculate the nth Fibonacci number modulo p:

```javascript
function fibonacciMod(n, p) {
    if (n <= 1) return n;

    // Matrix representation of Fibonacci sequence: [[1, 1], [1, 0]]
    const F = [[1, 1], [1, 0]];

    // Function to multiply two matrices under modulo p
    function multiplyMatrices(a, b, p) {
        let result = new Array(2).fill().map(() => new Array(2).fill(0));
        for (let i = 0; i < 2; i++) {
            for (let j = 0; j < 2; j++) {
                for (let k = 0; k < 2; k++) {
                    result[i][j] += a[i][k] * b[k][j];
                    result[i][j] %= p;
                }
            }
        }
        return result;
    }

    // Function to raise a matrix to the power of n under modulo p
    function matrixPower(matrix, n, p) {
        let result = [[1, 0], [0, 1]]; // Identity matrix

        while (n > 0) {
            if (n % 2 === 1) {
                result = multiplyMatrices(result, matrix, p);
            }
            matrix = multiplyMatrices(matrix, matrix, p);
            n = Math.floor(n / 2);
        }

        return result;
    }

    // Compute the nth Fibonacci number using matrix exponentiation
    let poweredMatrix = matrixPower(F, n - 1, p);

    // The first element of the resulting matrix gives us the nth Fibonacci number
    return poweredMatrix[0][0];
}

// Example usage:
console.log(fibonacciMod(10, 100)); // Output should be 55 % 100 = 55
```

