<?php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;

class FavoritesManager
{
    /**
     * Add a favorite name.
     *
     * @param string $name The name to add.
     */
    public function addFavorite(string $name): void
    {
        if (Auth::check()) {
            // User is logged in, save to database
            $favorite = new Favorite();
            $favorite->user_id = Auth::id();
            $favorite->name = $name;
            $favorite->save();
        } else {
            // Guest user, save to session
            $favorites = session('favorites', []);
            $favorites[] = $name;
            session(['favorites' => array_unique($favorites)]);
        }
    }

    /**
     * Remove a favorite name.
     *
     * @param string $name The name to remove.
     */
    public function removeFavorite(string $name): void
    {
        if (Auth::check()) {
            // User is logged in, delete from database
            Favorite::where('user_id', Auth::id())
                ->where('name', $name)
                ->delete();
        } else {
            // Guest user, remove from session
            $favorites = session('favorites', []);
            $favorites = array_diff($favorites, [$name]);
            session(['favorites' => array_values($favorites)]);
        }
    }

    /**
     * Get all favorite names.
     *
     * @return array An array of favorite names.
     */
    public function getFavorites(): array
    {
        if (Auth::check()) {
            // User is logged in, retrieve from database
            return Favorite::where('user_id', Auth::id())->pluck('name')->toArray();
        } else {
            // Guest user, retrieve from session
            return session('favorites', []);
        }
    }
}
