```rust
use std::env;
use std::io::{self, BufRead};

fn main() {
    // Get command line arguments excluding the executable name
    let args: Vec<String> = env::args().skip(1).collect();

    if args.is_empty() {
        eprintln!("Usage: {} <substring1> [<substring2> ...]", env::args().next().unwrap());
        return;
    }

    println!("Enter some text (press Ctrl+D to finish):");

