contract CredsToken is ERC1155, Ownable {
    // Define the types of credentials
    enum CredentialType { Degree, Certification, Badge }

    // Mapping from credential type to URI
    mapping(CredentialType => string) private _credentialURIs;

    event CredentialMinted(address indexed account, uint256 id, uint256 amount);

    constructor(string memory uriDegree, string memory uriCertification, string memory uriBadge) ERC1155("") {
        _setURI(uriDegree);
        _credentialURIs[CredentialType.Degree] = uriDegree;
        _credentialURIs[CredentialType.Certification] = uriCertification;
        _credentialURIs[CredentialType.Badge] = uriBadge;
