        if (tokenId == uint256(CredentialType.Degree)) return _credentialURIs[CredentialType.Degree];
        if (tokenId == uint256(CredentialType.Certification)) return _credentialURIs[CredentialType.Certification];
        if (tokenId == uint256(CredentialType.Badge)) return _credentialURIs[CredentialType.Badge];
        revert("Invalid token ID");
    }

    function setURI(string memory newURI) external onlyOwner {
        _setURI(newURI);
    }

    function getCredentialURI(CredentialType credentialType) external view returns (string memory) {
        return _credentialURIs[credentialType];
    }
}
```

