U_wind = 2.5; % Wind speed (m/s)

% Grid parameters
nx = 100; % Number of grid points along x-axis
ny = 100; % Number of grid points along y-axis
dx = L / (nx - 1); % Spatial step size along x-axis
dy = W / (ny - 1); % Spatial step size along y-axis

% Time parameters
