y = linspace(0, W, ny);
[X, Y] = meshgrid(x, y);

% Initial condition: flat surface
eta = zeros(nx, ny);

% Wave propagation function
function eta_new = wave_propagation(eta, U_wind, dx, dy, dt)
    % Simple linear advection equation for wave propagation
    eta_new = circshift(eta, [0, -round(U_wind * dt / dx)]);
end

% Main loop
