                .catch((error) => {
                    if (retryCount < maxRetries) {
                        console.log(`Attempt ${retryCount + 1} failed. Retrying...`);
                        setTimeout(() => attempt(retryCount + 1), 1000); // Retry after 1 second delay
                    } else {
                        console.error('Max retries reached. Request failed.');
                        reject(error);
                    }
                });
        };

        attempt(0);
    });
}

// Example usage:
const makeRequest = () => {
    return new Promise((resolve, reject) => {
        // Simulate a random success or failure
        const isSuccess = Math.random() > 0.5;
        if (isSuccess) {
            resolve('Request succeeded!');
        } else {
            reject(new Error('Request failed!'));
        }
    });
};

retryRequest(makeRequest)
    .then((result) => console.log(result))
    .catch((error) => console.error(error));
```

In this code snippet, `retryRequest` is a higher-order function that takes another function (`requestFunction`) as its argument and returns a promise. The inner `attempt` function handles the actual retry logic recursively.

The `makeRequest` function simulates a network request with a 50% chance of success or failure. You can replace it with your own asynchronous request function.

When calling `retryRequest`, you pass in the `makeRequest` function along with any additional options (e.g., customizing the maximum number of retries). If the request succeeds within the specified number of attempts, the promise will be resolved; otherwise, it will be rejected after reaching the maximum number of retries.

